#include <bits/stdc++.h>
using namespace std;
struct N{ long long v; int l, r; };
vector<N> t;
bool ok(int i, long long lo, long long hi){
 if(i==-1) return true;
 if(!(lo < t[i].v && t[i].v < hi)) return false;
 return ok(t[i].l, lo, t[i].v) && ok(t[i].r, t[i].v, hi);
}
int main(){int n; scanf("%d",&n); t.resize(n);
 for(int i=0;i<n;i++) scanf("%lld %d %d",&t[i].v,&t[i].l,&t[i].r);
 puts(ok(0, LLONG_MIN, LLONG_MAX)?"VALID":"INVALID"); return 0;}
